def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    my_def = 0
    opp_def = 0
    for i in range(n):
        if me[i] == 'D':
            my_def += 1
        if opp[i] == 'D':
            opp_def += 1

    last_me = me[-1]
    last_opp = opp[-1]

    # Probe if we haven't defected yet and opponent has been cooperative.
    if my_def == 0 and opp_def == 0 and n >= 5:
        return 'D'

    # Exploit if opponent never defected and we have probed and then cooperated.
    if opp_def == 0 and my_def > 0:
        first_d = -1
        for i in range(n):
            if me[i] == 'D':
                first_d = i
                break
        if first_d != -1:
            has_c_after = False
            for i in range(first_d + 1, n):
                if me[i] == 'C':
                    has_c_after = True
                    break
            if has_c_after:
                return 'D'
            elif last_me == 'D':
                return 'C'

    # If opponent has a high defection rate, defect always.
    if n >= 10 and opp_def > n * 0.3:
        return 'D'

    # If opponent is heavily defecting recently, defect.
    recent_len = min(5, n)
    recent_opp_def = 0
    for i in range(n - recent_len, n):
        if opp[i] == 'D':
            recent_opp_def += 1
    if recent_opp_def >= 3:
        return 'D'

    # If opponent defects while we cooperate frequently, defect.
    lookback = min(10, n)
    cd_recent = 0
    for i in range(n - lookback, n):
        if me[i] == 'C' and opp[i] == 'D':
            cd_recent += 1
    if cd_recent >= 3:
        return 'D'

    # Standard TFT with forgiveness.
    if last_opp == 'D':
        if my_def == 1 and opp_def == 1:
            return 'C'
        k = 0
        for i in range(n-1, -1, -1):
            if opp[i] == 'D':
                k += 1
            else:
                break
        if k >= 3:
            return 'D'
        if last_me == 'D':
            return 'C'
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        return 'C'

    return 'C'
